let parsed;
try {
  parsed = JSON.parse(qaResponse);
} catch (e) {
  parsed = { passed: false, reason: 'Invalid QA JSON output' };
}

// Strict QA validation (Blocker 6): Only strictly boolean true is accepted
const isPassed = typeof parsed.passed === 'boolean' && parsed.passed === true;
const reason = typeof parsed.reason === 'string' && parsed.reason.trim() 
  ? parsed.reason 
  : (isPassed ? 'QA Passed' : 'QA rejected proposal without detailed reason.');

// Strict attempt validation (Blocker 2):
const upstreamItem = $input.item.json || {};
const attempt = upstreamItem.attempt;
if (!Number.isInteger(attempt) || attempt < 1 || attempt > 3) {
  throw new Error('FAIL_CLOSED_SYSTEM_ERROR: Missing or invalid business attempt in QA Verdict Parser. Expected integer between 1 and 3, got: ' + attempt);
}

return { 
  json: { 
    ...upstreamItem,
    passed: isPassed, 
    reason: reason,
    attempt: attempt
  } 
};

