if (!Number.isInteger(currentAttempt) || currentAttempt < 1 || currentAttempt > 3) {
  throw new Error('FAIL_CLOSED_SYSTEM_ERROR: Missing or invalid business attempt in Check Attempt Limit. Expected integer between 1 and 3, got: ' + currentAttempt);
}

const nextAttempt = currentAttempt + 1;
const maxAttempts = 3;

// 2. Determine feedback source (Structural Error vs QA Rejection)
let feedback = '';
if (inputData.validation_status === 'SYSTEM_VALIDATION_ERROR') {
  feedback = 'LỖI CẤU TRÚC JSON (SYSTEM_VALIDATION_ERROR): ' + (inputData.validation_error || 'Output của Agent 1 không đúng định dạng JSON hoặc thiếu trường bắt buộc.') + ' Bạn BẮT BUỘC phải sửa lỗi này và trả về JSON hợp lệ đầy đủ 25 trường.';
} else if (inputData.reason) {
  feedback = inputData.reason;
} else {
  feedback = 'Bản kế hoạch bị từ chối do không đạt tiêu chuẩn chất lượng.';
}

// ZERO references to external nodes. Everything is preserved from inputData!
return {
  json: {
    ...inputData,
    attempt: nextAttempt,
    max_attempts: maxAttempts,
    is_blocked: nextAttempt > maxAttempts,
    qa_feedback: feedback
  }
};

